#!/usr/bin/env bash
# OWASP ZAP baseline (passive) scan of the running stack (PRD 12.1 security checks).
# Spiders the web app, imports the OpenAPI spec generated by Scribe (docs/api/openapi.yaml)
# with an admin bearer token so the API is reached, waits for the passive scanner and writes
# docs/testing/results/zap-baseline.md. No active attacks are sent ("baseline").
# ZAP_HOME: directory containing zap.sh (default ~/.local/zap/ZAP_*). Requires Java 17+.
set -uo pipefail
source "$(dirname "$0")/lib/env.sh"
OUT="$UC_ROOT/docs/testing/results"
mkdir -p "$OUT"
ZAP_SH="${ZAP_HOME:+$ZAP_HOME/zap.sh}"
[ -z "$ZAP_SH" ] && ZAP_SH="$(ls -d "$HOME"/.local/zap/ZAP_*/zap.sh 2>/dev/null | tail -1)"
if [ -z "$ZAP_SH" ] || [ ! -x "$ZAP_SH" ]; then
  echo "ZAP not found. Download the cross-platform package from https://www.zaproxy.org/download/ and set ZAP_HOME." | tee "$OUT/zap-summary.txt"
  exit 0
fi
BASE="${APP_URL%/}"
TOKEN=$(cd "$UC_ROOT/backend" && "$PHP" artisan tinker --execute 'echo App\Models\User::where("role","admin")->first()->createToken("zap-scan", ["*"], now()->addHour())->plainTextToken;' 2>/dev/null | tail -1)
WORK="$(mktemp -d)"
# Read-only copy of the spec: ZAP's OpenAPI job SENDS a request for every operation, so
# POST/PUT/PATCH/DELETE would change (or delete) real data. Keep only GET operations.
node -e '
  const fs = require("fs"); const [src, dst] = process.argv.slice(1)
  const lines = fs.readFileSync(src, "utf8").split("\n"); const out = []; let skip = false
  for (const l of lines) {
    const m = l.match(/^    (get|post|put|patch|delete|options|head):\s*$/)
    if (m) skip = m[1] !== "get"
    else if (/^  \S/.test(l) || /^\S/.test(l)) skip = false
    if (!skip) out.push(l)
  }
  fs.writeFileSync(dst, out.join("\n"))
' "$UC_ROOT/docs/api/openapi.yaml" "$WORK/openapi.yaml"
grep -qE "^    (post|put|patch|delete):" "$WORK/openapi.yaml" && { echo "refusing: write operations left in the spec" >&2; exit 1; }
cat > "$WORK/plan.yaml" <<YAML
env:
  contexts:
    - name: uniconnect
      urls: ["$BASE"]
      includePaths: ["$BASE.*"]
  parameters:
    failOnError: false
    progressToStdout: true
jobs:
  - type: replacer
    parameters: { deleteAllRules: true }
    rules:
      - description: bearer token
        matchType: req_header
        matchString: Authorization
        replacementString: "Bearer $TOKEN"
  - type: spider
    parameters: { context: uniconnect, maxDuration: 2 }
  - type: openapi
    parameters: { apiFile: "$WORK/openapi.yaml", targetUrl: "$BASE" }
  - type: passiveScan-wait
    parameters: { maxDuration: 5 }
  - type: report
    parameters:
      template: traditional-md
      reportDir: "$OUT"
      reportFile: zap-baseline
      reportTitle: "UniConnect — OWASP ZAP baseline (passive) scan"
YAML
"$ZAP_SH" -cmd -silent -notel -config connection.timeoutInSecs=30 -config "certificates.allowUnsafeSslRenegotiation=true" -autorun "$WORK/plan.yaml" > "$OUT/zap.log" 2>&1
REPORT="$OUT/zap-baseline.md"
if [ -f "$REPORT" ]; then
  node -e '
    const s = require("fs").readFileSync(process.argv[1], "utf8");
    const count = (r) => (s.match(new RegExp("\\| " + r + " \\| (\\d+) \\|")) || [, "0"])[1];
    console.log(`High ${count("High")}, Medium ${count("Medium")}, Low ${count("Low")}, Informational ${count("Informational")}`);
  ' "$REPORT" | tee "$OUT/zap-summary.txt"
else
  echo "ZAP ran but produced no report; see results/zap.log" | tee "$OUT/zap-summary.txt"
fi
rm -rf "$WORK"
